def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])

    # Same-color run lengths let us test rectangle edges efficiently.
    right = [[1] * C for _ in range(R)]
    down = [[1] * C for _ in range(R)]
    for r in range(R):
        for c in range(C - 2, -1, -1):
            if g[r][c] == g[r][c + 1]:
                right[r][c] = right[r][c + 1] + 1
    for r in range(R - 2, -1, -1):
        for c in range(C):
            if g[r][c] == g[r + 1][c]:
                down[r][c] = down[r + 1][c] + 1

    # Prefix sums to check that a frame color does not also occur inside it.
    pref = [[[0] * (C + 1) for _ in range(R + 1)] for _ in range(10)]
    for color in range(10):
        for r in range(R):
            row_sum = 0
            for c in range(C):
                row_sum += (g[r][c] == color)
                pref[color][r + 1][c + 1] = pref[color][r][c + 1] + row_sum

    def inside_count(color, top, bottom, left, right_edge):
        return (pref[color][bottom][right_edge]
                - pref[color][top + 1][right_edge]
                - pref[color][bottom][left + 1]
                + pref[color][top + 1][left + 1])

    candidates = []

    for top in range(R - 2):
        for bottom in range(top + 2, R):
            h = bottom - top - 1
            for left in range(C - 2):
                color = g[top][left]
                for right_edge in range(left + 2, C):
                    w = right_edge - left - 1
                    if h * w < 6:
                        continue
                    if (right[top][left] < right_edge - left + 1 or
                        right[bottom][left] < right_edge - left + 1 or
                        down[top][left] < bottom - top + 1 or
                        down[top][right_edge] < bottom - top + 1):
                        continue
                    if inside_count(color, top, bottom, left, right_edge):
                        continue

                    # Fit a repeating 2D tile to the framed interior.
                    best = None
                    for ph in range(1, min(12, h) + 1):
                        for pw in range(1, min(12, w) + 1):
                            if ph * pw > 64:
                                continue
                            buckets = [[0] * 10 for _ in range(ph * pw)]
                            sizes = [0] * (ph * pw)
                            for i in range(h):
                                for j in range(w):
                                    k = (i % ph) * pw + (j % pw)
                                    buckets[k][g[top + 1 + i][left + 1 + j]] += 1
                                    sizes[k] += 1

                            if min(sizes) < 2:
                                continue

                            tile = []
                            errors = 0
                            ratios = []
                            for k, counts in enumerate(buckets):
                                value = max(range(10), key=lambda x: counts[x])
                                tile.append(value)
                                errors += sizes[k] - counts[value]
                                ratios.append(counts[value] / sizes[k])

                            if errors / (h * w) > 0.14 or min(ratios) < 0.60:
                                continue

                            key = (ph * pw, errors, ph + pw)
                            if best is None or key < best[0]:
                                best = (key, ph, pw, tile, buckets, sizes)

                    if best is not None:
                        _, ph, pw, tile, buckets, sizes = best
                        candidates.append(
                            (top, bottom, left, right_edge, color,
                             ph, pw, tile, buckets, sizes)
                        )

    # Keep only maximal nested frames of each color.
    candidates.sort(
        key=lambda x: (-(x[1] - x[0]) * (x[3] - x[2]), x[4])
    )
    chosen = []
    for cand in candidates:
        t, b, l, rr, color = cand[:5]
        contained = False
        for other in chosen:
            ot, ob, ol, orr, ocolor = other[:5]
            if (color == ocolor and ot <= t and ob >= b and
                ol <= l and orr >= rr and
                (ot < t or ob > b or ol < l or orr > rr)):
                contained = True
                break
        if not contained:
            chosen.append(cand)

    votes = [[{} for _ in range(C)] for _ in range(R)]
    for t, b, l, rr, color, ph, pw, tile, buckets, sizes in chosen:
        for i in range(b - t - 1):
            for j in range(rr - l - 1):
                r, c = t + 1 + i, l + 1 + j
                k = (i % ph) * pw + (j % pw)
                value = tile[k]
                if g[r][c] == value:
                    continue
                count = buckets[k][value]
                confidence = count / sizes[k]
                votes[r][c][value] = votes[r][c].get(value, 0.0) + confidence

    for r in range(R):
        for c in range(C):
            if votes[r][c]:
                ranked = sorted(votes[r][c].items(),
                                key=lambda item: item[1], reverse=True)
                if len(ranked) == 1 or ranked[0][1] > ranked[1][1]:
                    g[r][c] = ranked[0][0]

    return g
